## Solution
```cpp[]
class Solution {
public:
    vector<int> findMissingRepeatingNumbers(vector<int> nums) {
        long long n = nums.size();

        // Sum formulas for [1..n]
        long long Sn  = n * (n + 1) / 2;
        long long S2n = n * (n + 1) * (2 * n + 1) / 6;

        long long S = 0, S2 = 0;
        for (int x : nums) {
            S  += x;
            S2 += (long long)x * x;
        }

        // Eq1: X - Y
        long long eq1 = S - Sn;
        // Eq2: X + Y  (derived from X^2 - Y^2 = S2 - S2n)
        long long eq2 = (S2 - S2n) / eq1;

        long long X = (eq1 + eq2) / 2;  // repeating
        long long Y = X - eq1;           // missing

        return {(int)X, (int)Y};
    }
};
```

